        # Determine the ray orientation from the closest side.
        distances = [c, w - 1 - c, r, h - 1 - r]
        d = min(range(4), key=lambda i: distances[i])
        if d == 0:
            for x in range(c - 1, -1, -1):
                if grid[r][x] != bg: break
                out[r][x] = color
        elif d == 1:
            for x in range(c + 1, w):
                if grid[r][x] != bg: break
                out[r][x] = color
        elif d == 2:
            for y in range(r - 1, -1, -1):
