    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            out[r][c] = 4
            # Extend toward the nearest non-background boundary/object in
            # the same row or column.
            rays = [
                (0, -1, c), (0, 1, w - 1 - c),
                (-1, 0, r), (1, 0, h - 1 - r)
            ]
            candidates = []
            for dr, dc, _ in rays:
                rr, cc = r + dr, c + dc
                path = []
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    path.append((rr, cc))
                    rr += dr
                    cc += dc
                if path and 0 <= rr < h and 0 <= cc < w:
                    candidates.append((len(path), path))
            if candidates:
                _, path = min(candidates, key=lambda x: x[0])
                for rr, cc in path:
                    out[rr][cc] = 3
    return out
